static int phase1_code_matches(const uint8_t *base, char *error, size_t capacity) {
    size_t i;
    for (i=0;i<sizeof(phase1_signatures)/sizeof(phase1_signatures[0]);++i) {
        if (memcmp(base+phase1_signatures[i].rva,phase1_signatures[i].bytes,32)) {
            snprintf(error,capacity,"phase1_code_mismatch rva=%08X",phase1_signatures[i].rva);
            return 0;
        }
    }
    return 1;
}
static int phase1_file_matches(HMODULE module) {
    static HMODULE verified;
    wchar_t path[32768];
    HANDLE file=INVALID_HANDLE_VALUE;
    BCRYPT_ALG_HANDLE alg=NULL;
    BCRYPT_HASH_HANDLE hash=NULL;
    unsigned char digest[32], *buffer=NULL;
    DWORD count=0;
    int success=0;
    const unsigned char expected[32]={0xc8,0xc1,0x44,0x40,0x4a,0xdf,0x61,0xa9,0xde,0x82,0x1c,0x99,0x66,0x82,0xa7,0xe6,0x6a,0xba,0xdd,0x7e,0x53,0x03,0x97,0xd3,0xbb,0xde,0x31,0xc1,0x23,0x20,0x3b,0xf7};
    if (verified==module && module) return 1;
    count=GetModuleFileNameW(module,path,32768);
    if (!count || count>=32768) return 0;
    file=CreateFileW(path,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,
                     NULL,OPEN_EXISTING,FILE_FLAG_SEQUENTIAL_SCAN,NULL);
    if (file==INVALID_HANDLE_VALUE) goto done;
    if (BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,NULL,0)<0) goto done;
    if (BCryptCreateHash(alg,&hash,NULL,0,NULL,0,0)<0) goto done;
    buffer=(unsigned char *)HeapAlloc(GetProcessHeap(),0,65536);
    if (!buffer) goto done;
    for (;;) {
        if (!ReadFile(file,buffer,65536,&count,NULL)) goto done;
        if (!count) break;
        if (BCryptHashData(hash,buffer,count,0)<0) goto done;
    }
    if (BCryptFinishHash(hash,digest,32,0)<0) goto done;
    const unsigned char capacity_profile[32]={0x2a,0xf8,0x31,0x39,0x57,0x62,0xad,0xf7,0xae,0xdf,0x59,0x67,0x7a,0x65,0x5b,0xbd,0x8a,0xa0,0x97,0xab,0x80,0xd0,0x37,0x22,0x8e,0xd2,0x6d,0x84,0xe3,0xb0,0xd8,0xe6};
    success=memcmp(digest,expected,32)==0 || memcmp(digest,capacity_profile,32)==0;
    if (success) verified=module;
done:
    if (buffer) HeapFree(GetProcessHeap(),0,buffer);
    if (hash) BCryptDestroyHash(hash);
    if (alg) BCryptCloseAlgorithmProvider(alg,0);
    if (file!=INVALID_HANDLE_VALUE) CloseHandle(file);
    return success;
}
